MAP
    NAME "SS_MAP_MCIR_MEDIDORES_SECTORES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_medidores_sectores.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_MCIR_MEDIDORES_SECTORES"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion.map'
        DATA "geometry from sectores_medidores using unique gid using srid=32614"
        TYPE POINT
        LABELITEM "sector"
        LABELCACHE on
        CLASS
            NAME "Sectores_medidores"
            STYLE
                SYMBOL "puntos"
                SIZE 8
                COLOR 0 0 0
                OUTLINECOLOR 0 0 0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 19
                COLOR 0 0 0
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP